<script setup lang="ts">
import { ref, watch } from 'vue'
import { errorText, formatDate, isCancelled, json, useApi } from '../api/system'
import { absoluteURL, copyText, currentUser, editSubscription, loadProfile, resetDraft, type Subscription } from '../api/accounts'
import { navigate } from '../router'
import Modal from './Modal.vue'
import AppIcon from './AppIcon.vue'
const props=defineProps<{paused:boolean}>();const api=useApi();const items=ref<Subscription[]>([]);const loading=ref(false);const error=ref('');const message=ref('');const confirm=ref<{item:Subscription;action:'delete'|'rotate'}|null>(null);const busy=ref(false)
async function load(){if(props.paused||loading.value)return;loading.value=true;try{items.value=(await api<{items:Subscription[]}>('/subscriptions')).items;error.value=''}catch(cause){if(!isCancelled(cause))error.value=errorText(cause)}finally{loading.value=false}}
watch(()=>props.paused,v=>{if(!v)void load()},{immediate:true})
function create(){resetDraft();navigate('nodes')}
function edit(item:Subscription){editSubscription(item);navigate('nodes')}
function url(item:Subscription,format?:string){const value=new URL(absoluteURL(item.url));if(format)value.searchParams.set('format',format);return value.href}
async function copy(item:Subscription,format?:string){try{await copyText(url(item,format));message.value=`${format==='clash'?'Clash ':format==='v2ray'?'v2ray ':''}订阅地址已复制。`}catch(cause){error.value=errorText(cause)}}
async function perform(){const action=confirm.value;if(!action||busy.value)return;busy.value=true;error.value='';try{if(action.action==='delete')await api(`/subscriptions/${action.item.id}`,json('DELETE'));else await api(`/subscriptions/${action.item.id}/rotate`,json('POST'));confirm.value=null;message.value=action.action==='delete'?'订阅已删除，原链接已失效。':'订阅令牌已重置，旧链接已失效。';await load();await loadProfile()}catch(cause){if(!isCancelled(cause))error.value=errorText(cause)}finally{busy.value=false}}
</script>
<template><section><div class="page-heading"><div><h1>我的订阅</h1><p class="muted">{{items.length}} / {{currentUser?.subscription_limit??1}} 条订阅</p></div><button class="primary" :disabled="items.length>=(currentUser?.subscription_limit??1)" @click="create"><AppIcon name="plus" />组合订阅</button></div><p v-if="error" role="alert" class="notice error">{{error}}<button @click="load">重试</button></p><p v-if="message" role="status" class="notice success">{{message}}</p><div v-if="!loading&&!items.length&&!error" class="panel empty-state"><AppIcon name="link" /><h3>创建你的第一条订阅</h3><p>在节点页勾选单个节点，或选取整个来源，再保存组合。</p><button class="primary" @click="create">选择节点<AppIcon name="right" /></button></div><article v-for="item in items" :key="item.id" class="panel subscription-card"><div class="panel-heading"><div><h2>{{item.name}}</h2><p class="small muted">{{item.node_count}} 个节点 · {{item.source_count}} 个来源 · {{formatDate(item.updated_at)}}</p></div><button class="compact" @click="edit(item)"><AppIcon name="edit" />编辑节点</button></div><div class="copy-field"><input :aria-label="`${item.name} 订阅地址`" :value="url(item)" readonly /><button class="icon-button" :aria-label="`复制 ${item.name}`" title="复制订阅地址" @click="copy(item)"><AppIcon name="copy" /></button></div><div class="subscription-formats"><button @click="copy(item)">自动识别</button><button @click="copy(item,'clash')">Clash / Mihomo</button><button @click="copy(item,'v2ray')">v2ray</button><span class="small muted">链接包含访问令牌</span></div><div class="subscription-maintenance"><button class="text-button" @click="confirm={item,action:'rotate'}"><AppIcon name="reset" />重置链接</button><button class="text-button danger" @click="confirm={item,action:'delete'}"><AppIcon name="trash" />删除订阅</button></div></article><Modal v-if="confirm" :title="confirm.action==='delete'?'删除订阅':'重置订阅链接'" :busy="busy" @close="confirm=null"><p>{{confirm.action==='delete'?'删除后原订阅链接立即失效。':'重置后旧订阅链接立即失效，需要在客户端替换为新地址。'}}</p><p v-if="error" class="notice error">{{error}}</p><div class="dialog-actions"><button :disabled="busy" @click="confirm=null">取消</button><button class="danger-solid" :disabled="busy" @click="perform">确认{{confirm.action==='delete'?'删除':'重置'}}</button></div></Modal></section></template>
